def create_test_file(path: Path, content: str, encoding: str = 'utf-8') -> Path:
    """Create a test file with specified content."""
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding=encoding)
    return path


def create_test_directory(base_path: Path, structure: Dict[str, Any]) -> Path:
    """Create a test directory structure from a dictionary."""
    for name, content in structure.items():
        path = base_path / name
        if isinstance(content, dict):
            path.mkdir(parents=True, exist_ok=True)
            create_test_directory(path, content)
        else:
            create_test_file(path, content)
    return base_path


def generate_random_code(lines: int = 10) -> str:
    """Generate random Python code for testing."""
    functions = ["process", "analyze", "transform", "validate", "compute"]
    code_lines = []
    for _ in range(lines):
        func_name = random.choice(functions)
        code_lines.append(f"def {func_name}_{random.randint(1000, 9999)}():")
        code_lines.append(f"    return {random.randint(0, 100)}")
    return "\n".join(code_lines)


